import type { Readable } from 'node:stream'

export interface StoredFile {
  stream: Readable
  size: number | null
}

/**
 * Object storage abstraction. Keys are always generated by the server — never taken from user input.
 *   public/…   world-readable assets (banners, logos, avatars, speaker photos)
 *   private/…  form uploads; only served through authorised routes
 */
export interface StorageDriver {
  readonly name: string
  put(key: string, body: Buffer, contentType: string): Promise<void>
  get(key: string): Promise<StoredFile | null>
  delete(key: string): Promise<void>
}

const SAFE_KEY = /^[A-Za-z0-9][A-Za-z0-9/_.-]{0,400}$/

export function assertSafeKey(key: string): void {
  const segments = key.split('/')
  if (
    !SAFE_KEY.test(key) ||
    segments.some((segment) => segment === '..' || segment === '.' || segment === '')
  ) {
    throw new Error(`Unsafe storage key: ${key}`)
  }
}
